"""Update public copy from the merged dataset, without changing numerical arrays."""
from pathlib import Path
import hashlib,json,re
ROOT=Path(__file__).resolve().parents[1];DIST=ROOT/'dist'
def main():
    meta=json.loads((DIST/'data/metadata.json').read_text());east=next(b for b in meta['basins'] if b['id']=='eastasia');n=f"{meta['pixels']:,}";records=f"{meta['habitatRecords']:,}"
    p=DIST/'index.html';s=p.read_text('utf8')
    s=s.replace('65,348',n).replace('74,402',records).replace('55,688',f"{len(meta['products']['mur']['cells']):,}").replace('483 native SST cells',f"{len(meta['products']['oisst']['cells']):,} native SST cells").replace('483 خلية مصدر',f"{len(meta['products']['oisst']['cells']):,} خلية مصدر")
    lead=f'<p><strong>{n} habitat cells, {records} habitat records.</strong> The atlas covers the Red Sea, Gulf of Aden, Arabian Gulf, Gulf of Oman, East Asia and the western Pacific. A cell can contain several habitat groups. Select a study area, ecoregion or rectangle to explore its cells.</p>'
    s=re.sub(r'(<div class="dialog-body methods-en">)<p>.*?</p>',lambda m:m[1]+lead,s,count=1)
    paragraph=f'<h3>East Asia and western Pacific</h3><p>{east["pixels"]:,} of 150,773 source habitat cells meet the 5 km marine MUR attachment limit. They span {len(east["regions"])} MEOW ecoregions. Monthly days come from archived daily MHW masks. Temperature intensity uses the saved SST anomaly, seasonal climatology and 90th-percentile threshold, in degrees Celsius. MUR has three missing dates: 20–21 February 2021 and 9 November 2022.</p><p>Coral and mangrove footprints use the study UNEP-WCMC inventories. East Asian seagrass cells include modelled top-percent suitability grids for three Zostera species. Kelp and macroalgae cells represent occurrence records. The East Asia coverage layer shows these study grid cells. These different footprint sources are retained in the source notes.</p>'
    if '<h3>East Asia and western Pacific</h3>' not in s:s=s.replace('<h3>Annual reconstruction</h3>',paragraph+'<h3>Annual reconstruction</h3>',1)
    s=s.replace('The habitat gallery uses original Red Sea photographs','The habitat gallery uses original photographs from across the atlas').replace('The original-resolution JPEGs are retained without edits; the page crops their display to fit the cards.','The original JPEGs are retained. Each point shows the nearest photograph in the collection, with its distance and source location. Coordinates marked as photo areas are approximate.')
    ar=f'<h3>شرق آسيا وغرب المحيط الهادئ</h3><p>تضيف المنطقة {east["pixels"]:,} خلية موائل ضمن {len(east["regions"])} إقليمًا بيئيًا. تُستخرج الأيام الشهرية من سجلات الموجات اليومية المحفوظة، وتحسب الشدة بدرجات مئوية فوق عتبة المئين التسعين. تضم الأعشاب البحرية نطاقات من نماذج ملاءمة لثلاثة أنواع من Zostera، وتمثل الطحالب الكبيرة سجلات وجود. تعرض طبقة التغطية خلايا هذه الدراسة. تبقى التواريخ الثلاثة المفقودة من MUR دون ملء.</p>'
    if '<h3>شرق آسيا وغرب المحيط الهادئ</h3>' not in s:s=s.replace('<div class="dialog-body methods-ar" lang="ar" dir="rtl">','<div class="dialog-body methods-ar" lang="ar" dir="rtl">'+ar)
    s=s.replace('original Red Sea and Arabian Gulf', 'Red Sea, Arabian Gulf and East Asia')
    p.write_text(s,encoding='utf8',newline='\n')
    p=DIST/'point-report.js';s=p.read_text('utf8').replace('Habitats: UNEP-WCMC study inventories.','Habitats: UNEP-WCMC inventories; East Asia also uses modelled seagrass grids and macroalgae occurrence records.');p.write_text(s,encoding='utf8',newline='\n')
    p=ROOT/'README.md';s=p.read_text('utf8');s=s.replace('# Red Sea & Arabian Gulf Habitat Heatwave Atlas','# Coastal Habitat Heatwave Atlas',1)
    intro=f'A static atlas of **{n} habitat cells** across the Red Sea, Arabian Gulf, East Asia and western Pacific. It includes coral, seagrass, mangrove and kelp/macroalgae footprints, annual and monthly marine heatwave histories, native daily OISST temperature, climate indices and separately backtested seasonal probabilities.'
    start=s.index('\n\n');end=s.index('\n\n',start+2);s=s[:start+2]+intro+s[end:]
    s=s.replace('Select both study areas, the Red Sea, or the Arabian Gulf; filter their MEOW ecoregions.','Start with a map rectangle or select any of the three study areas and their MEOW ecoregions.').replace('choosing both study areas shows both sets','choosing all study areas shows each set')
    s+='\n\n## East Asia extension — 18 October 2026\n\n'+f'The independent export retains {east["pixels"]:,} of 150,773 study sites after valid marine MUR attachment within 5 km. It adds {len(east["regions"])} ecoregions. Earlier Red Sea and Gulf numerical slices are preserved and checked by `test_eastasia.py`. Native quarterly and monthly records, daily OISST and habitat/region training outcomes are appended independently.\n\nThe source `exceedance` field is an integer threshold flag, not temperature. East Asia temperature intensity is calculated from saved anomaly + climatology − p90 threshold on the saved event mask. Annual frequency follows the existing no-leap/year-boundary convention. Missing MUR dates (2021-02-20, 2021-02-21, 2022-11-09) remain absent.\n\nEast Asia seagrass footprints include modelled top-percent suitability grids for Zostera marina, Z. japonica and Z. caespitosa; kelp/macroalgae footprints are occurrence based. Coverage, reports and methods retain this distinction.\n\nInterface labels are available in English, Arabic, simplified/traditional Chinese, Japanese, Korean, Filipino, Indonesian, Malay, Vietnamese, Russian and Persian. Scientific source titles retain their original wording; PDF reports use English. Photos use verified open licences and geographic coordinates or explicitly approximate named areas. The nearest photo is not presented as a photograph of the selected heatwave cell.\n\nThe weekly GitHub workflow refreshes climate observations and refits seasonal models for all three study areas. Historical MHW arrays stay frozen through 2025. Future annual dotted lines are conditional on the stated climate inputs; seasonal probability lines describe the whole forecast season.\n'
    p.write_text(s,encoding='utf8',newline='\n')
    notes={'habitatCells':meta['pixels'],'habitatRecords':meta['habitatRecords'],'basins':[{k:v for k,v in b.items() if k!='regions'} for b in meta['basins']],'ecoregions':len(meta['regions']),'nativeCells':{p:len(v['cells']) for p,v in meta['products'].items()},'sourceInventory':'Canonical East Asia footprint, 20260402','seagrass':'Species-specific top-percent suitability grids; three Zostera species','kelp_macroalgae':'Darwin Core occurrence footprint; all-record main branch'}
    (DIST/'data/coverage_notes.json').write_text(json.dumps(notes,separators=(',',':')),encoding='utf8')
    print(json.dumps(notes,ensure_ascii=False,indent=2))
if __name__=='__main__':main()
